Assume $Z$ is defined as Eq.(12), and can be described as $Z = \sum_{k \in [K]} \sum_{j \in [J_k]} \omega_{kj} Z_{kj}$.  

    Suppose Assumption~2 holds, and for each $k \in [K]$, $j \in [J_k]$, $b_{kj} = b$. Then, 
























        \begin{enumerate}[(1)]
            \item for every $t > 0$,
                \begin{align}

                    \mathbb{P} (Z \geq \mathbb{E}[Z]  + t) \leq \exp \left( -\frac{v}{W} \varphi \left( \frac{tW}{Uv}\right) \right) 
                    \leq \exp  \left( - \frac{v}{ \sum_{k \in [K]} \chi_{f} (G_k)} \varphi \left( \frac{4t}{5v}\right) \right) ,
                \end{align}
            where $\varphi$ is defined in Eq.(13), $v = (1 + b) \mathbb{E} [Z] + \sigma^2$, $\sigma^2 = \sum_k \sum_j \omega_{kj} \sigma_{kj}^2$, $W = \sum_{k \in [K]} \chi_f(G_k) = \sum_{k \in [K]} \omega_k$, and $U = \sum_{k \in [K]} U_k$, $U_k = \sum_{j \in J_k} \max (1, v_{kj}^{\frac{1}{2}} W^{\frac{1}{2}} v^{-\frac{1}{2}})$; 





            \item for every $t > 0$,~\footnote{Note that, Eq.~(15) is usually called the Bernstein-type inequality~[concentration13initial].}

                \begin{align}

                    \mathbb{P} (Z   \geq     \mathbb{E}[Z] + \sqrt{2cvt} + \frac{2ct}{3}) \leq e^{-t} ,
                \end{align}
            where $c = \frac{5^2}{4^2} \sum_{k \in [K]} \chi_{f} (G_k)$.
        \end{enumerate}

$Z = \sum_{k \in [K]} \sum_{j \in [J_k]} \omega_{kj}Z_{kj} $ (see details in Eq. (12), Section 3).  

    Suppose Assumption 2 holds, and for every $k \in [K], j \in [J_k]$,  $b_{kj}=b, ~\omega_{kj}=1$. Then 









        \begin{enumerate}[(1)]
            \item for every $t > 0$,
                \begin{align}

                    \mathbb{P} (Z \geq \mathbb{E}[Z] + t) \leq \exp \left( - v \varphi \left( \frac{t}{v { \sum_{k \in [K]} \chi_{f} (G_k)} } \right) \right) ,
                \end{align}

            where $v = (1 + b) \mathbb{E} [Z] + \sigma^2$, $W = \sum_{k \in [K]} \chi_f(G_k) = \sum_{k \in [K]} \omega_k$, and $\omega_k = |J_k|$, $U = \sum_{k \in [K]}$. Additionally,  $\varphi$ can be seen in  Eq.(13), i.e., $\varphi(x) = (1+x) \log(1+x)-x$;
            \item for every $t > 0$,
                \begin{align}


                    \mathbb{P} (Z \geq \mathbb{E} [Z] + c \sqrt{2vt} + \frac{2ct}{3}) \leq e^{-t} ,
                \end{align}
                where $c = \sum_{k \in [K]} \chi_{f} (G_k)$ (details in Appendix E.2).  
        \end{enumerate}

Let a function class $\mathcal{F} = \{ f = (f_1, f_2, \ldots, f_K) \}$, where each $f_k: \mathcal{X} \rightarrow \mathbb{R}$, and assume that all functions $f_k$ are measurable, square-integrable, and fulfill the conditions $\mathbb{E} [f_k({\mathbf{x}}_{kj})] = 0$ for all $k \in [K]$ and $j \in [m_k]$. Besides, we require that $\|f_k\|_{\infty} \leq 1$, i.e., $\sup_{{\mathbf{x}}} |f_k({\mathbf{x}})| \leq 1$. 

Define $Z$ as follows:
    \begin{align*}
        Z \overset{\textup{def}}{=} \sup_{f \in \mathcal{F}} \sum_{k \in [K]} \sum_{j \in [J_k]} \omega_{kj}  \sum_{i \in I_{kj}} f_k({\mathbf{x}}_i).
    \end{align*}


Furthermore, for each $k \in [K]$ and $j \in [J_k]$, let $\sigma_{kj}$ represent a positive real value such that $\sigma_{kj}^2 \geq \sum_{i \in I_{kj}} \sup_{f \in \mathcal{F}} \mathbb{E} [f^2({\mathbf{x}}_i)]$. 
Then, for every $t \geq 0$,

\begin{align}
    \mathbb{P} (Z \geq \mathbb{E}[Z] + t) \leq \exp \left( - \frac{v}{ \sum_{k \in [K]} \chi_{f} (G_k)} \varphi \left( \frac{4t}{5v}\right) \right) ,
\end{align}
        where $v = \sum_{k \in [K]} \sum_{j \in [J_k]} \omega_{kj} \sigma_{kj}^2 + 2 \mathbb{E} [Z]$. 

        Also, with probability at least $1 - e^{-t}$,
        \begin{align}
            Z \leq \mathbb{E}[Z] + \sqrt{2cvt} + \frac{2ct}{3} , 
        \end{align}
        where $c = \frac{5^2}{4^2} \sum_{k \in [K]} \chi_{f} (G_k)$.

Denote ${\mathbf{X}}$ as some random variables, which are divided in the same way as the Section 2, i.e., ${\mathbf{X}} = ({\mathbf{X}}_1,{\mathbf{X}}_2,\dots,{\mathbf{X}}_K)$. For every $k \in [K]$, ${\mathbf{X}}_k = ({\mathbf{x}}_{k1},{\mathbf{x}}_{k2},\dots,{\mathbf{x}}_{k m_k})$, with $m=\sum_{k \in [K]}m_k$. Assume that each ${\mathbf{X}}_k$ is linked to a dependence graph $G_k$, where $\{ (I_{kj}, \omega_{kj}) \}_{j \in [J_k]}$ constitues a fractional independent vertex cover of $G_k$, and define $\chi_{f} (G_k) \overset{\textup{def}}{=} \sum_{j \in [J_k]} \omega_{kj}$.












Let $\mathcal{F} = \{ f, f = (f_1,\dots,f_K) \}$, where each $f_k: \mathcal{X} \rightarrow \mathcal{Y}$, and assume that all functions $f_k$ are measurable, squareintegrable, and fulfill the conditions $\mathbb{E} [f_k({\mathbf{x}}_{kj})] = 0, ~\omega_{kj}=1$ for all $k \in [K]$ and $j \in [m_k]$. Additionally, we require that $\|f_k\|_{\infty} \leq 1$.
Define $Z$ as follows:
    \begin{align*}
        Z \overset{\textup{def}}{=} \sup_{f \in \mathcal{F}} \sum_{k \in [K]} \sum_{j \in [J_k]}  \sum_{i \in I_{kj}} f_k({\mathbf{x}}_i).
    \end{align*}








Moreover, for every $k \in [K]$, $j \in [J_k]$, donate a positive real value $\sigma_{kj}$, satisfying $\sigma_{kj}^2 \geq \sum_{i \in I_{kj}} \sup_{f \in \mathcal{F}} \mathbb{E}[f^2({\mathbf{x}}_i)]$. Then, for every $t \geq 0$,
\begin{align}
     \mathbb{P} (Z \geq \mathbb{E}[Z] + t) \leq \exp \left( - v \varphi \left( \frac{t}{v W}\right) \right) ,
\end{align}
where $v = \sum_{k \in [K]} \sum_{j \in [J_k]} \sigma_{kj}^2 + 2 \mathbb{E} [Z]$, $W = \sum _{k \in [K]} \chi _f(G_k) $, and the definition of other variables in Theorem 5. 
Also, with probability at least $1 - e^{-t}$,
\begin{align}
Z \leq \mathbb{E}[Z] + c \sqrt{2vt} + \frac{2ct}{3} , 
\end{align}
where $c = \sum_{k \in [K]} \chi_{f} (G_k)$.

Assume the function class $\mathcal{F}$ is defined in Eq.~(4). 
Assume that there is some $r>0$ for every $f \in \mathcal{F}$, $\mathrm{var}(f_k) \leq r$, $\max_{k \in {K}} \sup_{{\mathbf{x}}} |f_k({\mathbf{x}})| \leq 1$.
Then for every $t > 0$, with probability at least $1-e^{-t}$, 

\begin{align*}
     \sup_{f \in \mathcal{F}} (P f - P_m f) 
     \leq \inf_{\alpha > 0} \left(2(1 + \alpha) \mathcal{R} (\mathcal{F} , r) + \sqrt {\frac{2crt}{K}} + (\frac{2}{3} + \frac{1}{\alpha})\frac{ct}{K} \right) ,
\end{align*}
where $c=\frac{5^2}{4^2} \sum_k \frac{\chi_f(G_k)}{m_k}$. Moreover, the same results hold for the quantity $\sup _{f \in \mathcal{F}} (P _m f - P f)$. For every $t> 0 $, with probability at least $1-e^{-t}$, 
\begin{align*}
    \sup _{f \in \mathcal{F}} (P _m f - P f) 
    \leq \inf_{\alpha > 0} \left(2(1 + \alpha) \mathcal{R} (\mathcal{F} , r) + \sqrt {\frac{2crt}{K}} + (\frac{2}{3} + \frac{1}{\alpha})\frac{ct}{K} \right) .
\end{align*}

For every $ r > 0 $, 
\begin{align}
    \mathbb{E} _{S,S'}  \sup _{f \in \mathcal{F}} \sum _{k \in [K]} \sum _{j \in [J_k]}  \frac{\omega_{kj}}{K m_k}  \sum _{i \in I_{kj}} ( f_k({\mathbf{x}}'_i) - f_k({\mathbf{x}}_i)) \leq 2 \mathcal{R} (\mathcal{F},r) .
\end{align}

Assume that the loss function $L : \mathcal{X} \times \mathcal{X} \times \mathcal{H}_k \rightarrow R_+ $ is bounded by $M_c$, and $\mathcal{\tilde{H}}_ {l,r} = \{ \tilde{h}: \tilde{h} \in \mathcal{\tilde{H}}, \mathrm{var}( L_{\tilde{h}_k}) \leq r \}$, where $\widetilde{{\mathbf{x}}}_{kl} = (\widetilde{{\mathbf{x}}}_{kl}^+, \widetilde{{\mathbf{x}}}_{kl}^-)$. For each $h \in \mathcal{H}_{l,r}$, $\alpha > 0 $ and $t > 0$,  with probability at least $1 - e^{-t}$, 
\begin{align*}
   & P (L_h) - P _m (L_h) \leq  2(1 + \alpha) \mathcal{R}( \mathcal{H}_{l,r}) + \\
   & \frac{5}{4} \sqrt{\frac{2rt}{\tilde{n}} \cdot \frac{1}{K} \sum _{k \in [K]} \frac{1}{\tau_k}} +  \frac{5^2}{4^2} (\frac{2}{3} + \frac{1}{\alpha}) (\frac{1}{K} \sum_{k \in [K]} \frac{1}{\tau_k}) \frac{t}{\tilde{n}},
\end{align*}
where $P(L_{\tilde{h}}), P_m(L_{\tilde{h}})$ can be obtained by Eq.(2), i.e., $P_m(L_{\tilde{h}}) = \frac{1}{K}\sum_{k \in [K]} \sum_{j \in [J_k]}\frac{\omega_{kj}}{m_k} \sum_{i \in {I_{kj}}} L({\mathbf{x}}_i,y_i,\tilde{h}_k)$ and $P_{\tilde{h}} = \mathbb{E}(P_m (L_{\tilde{h}}))$.

Assume that there are some functional $T : \mathcal{F}_k \rightarrow \mathbb{R}^+$ and some constant $B$, for all $f \in \mathcal{F}, T(f_k) \in [\mathrm{var}(f_k), B\mathbb{E} f_k]$. 

If a sub-root function $\Phi$ and its fixed point $r^*$


satisfy:~\footnote{Notably, here the content in $\{\}$ of $\mathcal{R}\{\}$ means adding some conditions to the function class (e.g., $T(f_k) \leq r$).}




\begin{align} 
    \forall r \geq r^*, ~
    \Phi (r) \geq B \mathcal{R} \{ f \in \mathcal{F}, T(f_k) \leq r \}.
\end{align}
Then for each $f\in \mathcal{F}$, $M >1$ and $t > 0$, with probability at least $1 - e^{-t}$, the following holds:
 \begin{align} 
    P f \leq \frac{M}{M-1} P _m f + \frac{c_1 M}{B} r^* + (c_2 BM +22 ) \frac{ct}{K},  
\end{align}



where $c_1 = 704$, $c_2 = 26$, and $c = \frac{5^2}{4^2} \sum_{k \in K}\frac{\chi_f(G_k)}{m_k} $.

Assume the loss function satisfies Assumption 1. 



There exists a sub-root function $\Phi$ and its fixed point $r^*$, satisfying



        \begin{align*}
           \forall r \geq r^*, ~  \Phi (r) \geq B \mu \mathcal{R} \{ h \in \mathcal{H}, \mu^2 \mathbb{E} (h_k - h_k^*)^2 \leq r \}.
        \end{align*}
    Then for every $t > 0$ and $ r \geq \Phi(r)$, with probability at least $1 - e^{-t}$, 
    \begin{align}  
        P (L_ {\hat{h}} - L_{h^*}) \leq \frac{c_1 }{B} r + (c_2 B  + 22) \frac{ct}{K},  
    \end{align}
    where $c_1 = 704$, $c_2 = 26$ and $c = \frac{5^2}{4^2} \sum_{k \in K}\frac{\chi_f(G_k)}{m_k}$.

Suppose a loss function satisfies the following conditions:


\begin{enumerate}[(1)]
\setlength\itemsep{-0.2pt}
    \item $L$ is $\mu $-Lipschitz continuous, i.e., $\forall k \in [K], i \in [m_k]$, $|L({\mathbf{x}}_{ki},y_{ki},h_k')-L({\mathbf{x}}_{ki},y_{ki},h_k'')| \leq \mu |h_k'({\mathbf{x}}_{ki})-h_k''({\mathbf{x}}_{ki})|$, 
    where $h_k', ~h_k'' \in \mathcal{H}_k$; 
    \item There is a constant $B > 1$ such that $\forall h \in \mathcal{H}, P(h-h^*)^2 \leq BP(L_h-L_{h^*})$.~\footnote{Note that this condition is usually met from a uniform convexity condition of $L$. In later applications of Macro-AUC and experiments, we assume $L \in [0, B]$, making this condition follow, which is easily met in practice. }
\end{enumerate}

Let \( \hat{h} \) and \( h^* \) denote the prediction functions, which correspond to the minimum empirical loss and the minimum expected loss, respectively.

    Assume a bounded loss function $ L \in [0, M_c] $. Assume:

    a sub-root function $\Phi$ and its fixed point $r^*$ satisfied the following: 
    \begin{align*}
        \forall r \geq r^*,~  \Phi (r) \geq M_c \mathcal{R} \{ h \in \mathcal{H}, \mathbb{E} (L_{h_k} - L_{h_k^*})^2 \leq r \}.
    \end{align*}
    Then for every $t > 0$, with probability at least $1 - e^{-t}$, 
    \begin{align} 
        P (L_ {\hat{h}} - L_{h^*}) \leq \frac{c_1 }{M_c} r^* + (c_2 M_c  + 22) \frac{ct}{K},  
    \end{align}
    where $c_1 = 704$, $c_2 = 26$, and $c = \frac{5^2}{4^2} \sum_{k \in K}\frac{\chi_f(G_k)}{m_k} $.

Assume that the loss function $L$ satisfies Assumption 1, and $\hat{\tilde{h}}$ satisfies $P _m(L _{\hat{\tilde{h}}}) = \inf _{\tilde{h} \in \mathcal{\tilde{H}}} P(L_{\tilde{h}})$. Assume: \\
    \begin{align*}
        \Phi (r) \geq B \mu \mathcal{R} \{ \tilde{h} \in \mathcal{\tilde{H}}, \mu ^2 \mathbb{E}(\tilde{h}_k - \tilde{h}_k^*)^2 \leq r \},
    \end{align*}
    then for every $\tilde{h} \in \mathcal{\tilde{H}}$, with probability at least $1 - e^{-t}$,
    \begin{align*}
        \mathbb{P} (L_{\hat{h}} - L_{h^*}) \leq \frac{c_1}{B} r^* +c_2\frac{t}{K},
    \end{align*}
    where $c_1 = 704$, $c_2 = (26B + 22)c $, $c = \frac{5^2}{4^2} 
\frac{1}{\tilde{n}} \sum_{k \in [K]} \frac{1}{\tau_k} $. We can notice that $c_2$ is $O(\frac{1}{\tilde{n}} \sum_k \frac{1}{\tau_k})$.

Define $\kappa: \mathcal{X} \times \mathcal{X} \rightarrow \mathbb{R}$ as a Positive Definite Symmetric (PDS) kernel and let its induced reproducing kernel Hilbert space (RKHS) be $\mathbb{H}$. Assume for every $k \in [K]$, $f_k = \theta_k^T \phi({\mathbf{x}}_k)$, where a weight vector satisfies $\|\theta_k\|_2 \leq \widetilde{M}$, and $\phi: \mathcal{X} \rightarrow \mathbb{H}$. 
For every $r >0$, the LFRC of function class $\mathcal{F}$ satisfies 
    \begin{align*}
        \mathcal{R}\{ f \in \mathcal{F}, \mathbb{E} f_k^2 \leq r \}  
        \leq \sum _{k \in [K]} \left(\frac{2 \chi_f(G_k)}{K m_k} \sum _{l=1}^{\infty} \min \{ r, \widetilde{M}^2 \lambda_{kl} \} \right)^{\frac{1}{2}},
    \end{align*}

where for every $k \in [K]$, the eigenvalues $(\lambda _{kl})_{l=1} ^{\infty}$

are arranged in a nonincreasing order, which satisfies $\kappa_k ({\mathbf{x}},{\mathbf{x}}') = \sum _{l =1} ^{\infty} \lambda_{kl} \varphi_{kl}({\mathbf{x}})^T \varphi _{kl}({\mathbf{x}}') $. 

Moreover, if for every $k \in [K]$, $\lambda_{k 1} \geq \frac{1}{m_k \widetilde{M}^2}$. 

Then for every $r \geq \frac{1}{m}$ and $m=\sum_{k \in [K]} m_k$, 
\begin{align*}
    \mathcal{R}\{ f \in \mathcal{F}, \mathbb{E} f_k^2 \leq r \}  
    \geq c \sum _{k \in [K]} \left(\frac{ \chi_f(G_k)}{K m_k} \sum _{l=1}^{\infty} \min \{ r, \widetilde{M}^2 \lambda_{kl} \}\right)^{\frac{1}{2}},
\end{align*}
where $c$ is a constant.

Suppose a loss function $L$ satisfies Assumption 1.

Assume $\sup _{{\mathbf{x}} \in \mathcal{X}} \kappa({\mathbf{x}},{\mathbf{x}}) < \Lambda$ and for every $k \in [K]$, $f_k = \theta_k^T \phi({\mathbf{x}}_k)$, where a weight vector satisfies $\|\theta_k\|_2 \leq \widetilde{M}$, and $\phi: \mathcal{X} \rightarrow \mathbb{H}$. 


For all $t > 0$, with probability at least $1 - e^{-t}$, we have \footnote{$a$ $\lesssim$ $b$ means $a$ $\leq$ $Cb$, where $C$ is a constant.}



\begin{align} 
    P (L_{\hat{h}} - L_{h^*}) \lesssim r^* + \frac{ t}{K} \sum_{k \in [K]} \frac{\chi_f(G_k)}{m_k},
\end{align}








where
\begin{align} 
    r^* \leq \sum _{k \in [K]} \min _{d_k \geq 0} \left( \frac{d_k \chi_f(G_k)}{K m_k} + \widetilde{M} \sqrt{\frac{\chi_f(G_k)}{K m_k} \sum _{l >d_k} \lambda_{kl}} \right).
\end{align}

Assume $\sup_{{\mathbf{x}}} \kappa({\mathbf{x}},{\mathbf{x}}) < \Lambda$. Assume that for every $k$,  $\tilde{h}_k = \theta_k^T\phi(\widetilde{{\mathbf{x}}})$, $\|\theta_k\|_2 \leq \widetilde{M}$, and the loss function $L$ satisfies Assumption 1. 



    Then, with probability at least $1 - e^{-t}$, 
\begin{align} 
    P (L_{\hat{h}} - L_{h^*}) \lesssim r^* + \frac{t}{K \tilde{n}} \sum_{k \in [K]} \frac{1}{\tau_k},
\end{align}
where $r^* \leq \sum _{k \in [K]} \min _{d_k \geq 0} (\frac{1}{\tilde{n}} \cdot \frac{d_k}{K \tau_k} + \widetilde{M} \sqrt{\frac{1}{\tilde{n}} \cdot \frac{1}{K \tau_k} \sum _{l >d_k} \lambda_{kl}}).$

Assume that $\sup _{{\mathbf{x}} \in \mathcal{X}} \|{\mathbf{x}}\|_2^2 \leq \bar{M}^2$, $\bar{M} >0$. The function class $\mathcal{F} = \{ f, f = (f_1,f_2,\dots,f_K), f_k = \theta_k^T {\mathbf{x}}_k, \|\theta_k\|_2 \leq \widetilde{M} \}$. For every $ r >0$, 
    \begin{align*}
       & \mathcal{R}\{ f \in \mathcal{F}, \mathbb{E} f_k^2 \leq r \} \leq \sum _{k \in [K]} \left( \frac{2 \chi_f(G_k)}{K m_k} \sum _{kl = 1} ^{\infty} \min \{ \frac{r}{\bar{M}^2} , \widetilde{M}^2 \widetilde{\lambda} ^2_{l} \} \right)^ {\frac{1}{2}}. \\


    \end{align*}
where singular values $(\widetilde{\lambda}_l)_{l=1}^{\infty}$ in a nonincreasing order, and $\Theta = \sum_{l=1}^{\infty}u_l v_l^T \widetilde{\lambda}_l$, where $\Theta$ is a weight matrix. 

Moreover, if $\widetilde{\lambda}_1^2 \geq \frac{1}{m \widetilde{M}^2}$, then for every $r \geq \frac{\bar{M}^2}{m}$, $m = \sum_{k \in [K]} m_k$,
\begin{align*}
     \mathcal{R}\{ f \in \mathcal{F}, \mathbb{E} f_k^2 \leq r \}  
     \geq c \sum_k \left(  \frac{ \chi_f(G_k)}{K m_k} \sum _{l = 1} ^{\infty} \min \{ \frac{r}{\bar{M}^2} , \widetilde{M}^2 \widetilde{\lambda} ^2_{l} \} \right)^{\frac{1}{2}},    
\end{align*}
where c is a constant.

Assume that $\sup _{{\mathbf{x}} \in \mathcal{X}} $ $ \|{\mathbf{x}}\|_2^2 \leq \bar{M}^2,\bar{M} > 0$, $\|\theta_k\|_2 \leq \widetilde{M}$, and loss function $L$ satisfies Assumption 1, $C$ is a constant about $B, \mu $, and $C'$ is a constant about $\chi_f(G)$. Then for all $t > 0$,  with probability at least $1 - e^{-t}$, 
\begin{align}
    P (L_{\hat{h}} - L_{h^*}) \leq C_{B,\mu} (r^* + C'_{\chi_f(G)} \frac{t}{K}),
\end{align}
where
\begin{small}
    \begin{align} 
    r^* \leq \sum_k \min_{d \geq 0} ( \frac{d}{\bar{M}^2} \frac{\chi_f(G_k)}{K m_k} + \widetilde{M} \sqrt{ \frac{\chi_f(G_k)}{K m_k} \sum_{l > d} \widetilde{\lambda}_{l}^2 } ) ,
    \end{align}
\end{small}
where $d$ is the division of singular values of matrix $\Theta$, and $P (L_{\hat{h}} - L_{h^*})$ can be seen in Theorem 1.

Assume that $\sup _{{\mathbf{x}} \in \mathcal{X}} $ $ \|{\mathbf{x}}\|_2^2 \leq \bar{M}^2,\bar{M} > 0$. The hypothesis $\mathcal{\tilde{H}}=\{ \tilde{h},\tilde{h}=(\tilde{h}_1,\dots,\tilde{h}_K), ~\tilde{h}_k = \theta_k^T {\mathbf{x}}, ~\|\theta_k\|_2 \leq \widetilde{M} \}$. And the loss function $L$ satisfies Assumption 1, $C$ is a constant about $B, \mu $. Then with probability at least $1 - e^{-t}$, 
\begin{align} 
    P (L_{\hat{h}} - L_{h^*}) \leq C_{B,\mu} (r^* + \frac{C'_{\tau_1,\tau_2,...\tau_K}}{K} \frac{ t}{\tilde{n}}),
\end{align}
where



\begin{align} 
    r^* \leq 2 \sum_k \min_{d_k \geq 0} ( \frac{1}{\bar{M}^2} \cdot \frac{d_k}{\tilde{n} K} \frac{1}{\tau_k} + \widetilde{M} \sqrt{\frac{1}{\tilde{n} K} \cdot \frac{1}{\tau_k} \sum_{l > d} \widetilde{\lambda}_{l}^2 } ),
\end{align}
where $d$ is the division of singular values of matrix $\Theta$.
